package legacy

import (
	"bytes"
	"embed"
	"net/http"
	"strconv"
	"time"

	"github.com/GRbit/whisper-hub/internal/core"
)

// static holds the reference's own output, regenerated by
// testdata/reference/capture.sh: the per-engine OpenAPI schemas, the
// Swagger UI and ReDoc pages, and the Swagger UI files the upstream image
// bundles under /assets (Apache-2.0, see static/swagger-ui-LICENSE).
//
//go:embed static
var static embed.FS

func mustStatic(name string) []byte {
	b, err := static.ReadFile("static/" + name)
	if err != nil {
		panic(err)
	}
	return b
}

var pages = map[string]struct {
	file, ctype string
}{
	"/docs":                 {"docs.html", "text/html; charset=utf-8"},
	"/docs/oauth2-redirect": {"oauth2-redirect.html", "text/html; charset=utf-8"},
	"/redoc":                {"redoc.html", "text/html; charset=utf-8"},
}

// assets mirrors Starlette's StaticFiles answers for the bundled files.
// ETag and Last-Modified are upstream's values: Starlette derives them from
// the file mtime, which the image keeps from the swagger-ui release.
var assets = map[string]struct {
	file, ctype, etag string
	modified          time.Time
}{
	"/assets/swagger-ui.css": {"swagger-ui.css", "text/css; charset=utf-8",
		`"1f75e3c45431eb214a976d3c64d2c497"`, time.Date(2023, 10, 25, 8, 4, 2, 0, time.UTC)},
	"/assets/swagger-ui-bundle.js": {"swagger-ui-bundle.js", "text/javascript; charset=utf-8",
		`"bf9a037f741f03e7056f9e16f372a919"`, time.Date(2023, 10, 25, 8, 21, 23, 0, time.UTC)},
}

// openAPIFile picks the schema upstream would generate for the default
// model's engine. Upstream advertises vad_filter and word_timestamps only
// for faster_whisper, min/max_speakers only for whisperx and diarize only
// for whisperx with HF_TOKEN set (here: a diarization-capable model); any
// other engine gets the generic schema, which equals openai_whisper's.
func openAPIFile(m core.Model) string {
	switch {
	case m.Engine == "faster_whisper":
		return "openapi-faster_whisper.json"
	case m.Engine == "whisperx" && m.Capabilities.Diarize:
		return "openapi-whisperx_diarize.json"
	case m.Engine == "whisperx":
		return "openapi-whisperx.json"
	}
	return "openapi-openai_whisper.json"
}

func (s *Server) handleStatic(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet && r.Method != http.MethodHead {
		// Starlette joins a Python set here, so the reference's order is
		// not stable across restarts; this is the order captured.
		methodNotAllowed(w, "HEAD, GET")
		return
	}
	var body []byte
	ctype := "application/json"
	if p, ok := pages[r.URL.Path]; ok {
		body, ctype = mustStatic(p.file), p.ctype
	} else {
		m := s.model(r.Context(), "")
		file := openAPIFile(m)
		s.log.Debug("legacy: serving openapi", "engine", m.Engine, "file", file)
		body = mustStatic(file)
	}
	w.Header().Set("Content-Type", ctype)
	w.Header().Set("Content-Length", strconv.Itoa(len(body)))
	w.WriteHeader(http.StatusOK)
	if r.Method != http.MethodHead {
		w.Write(body)
	}
}

func (s *Server) handleAsset(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet && r.Method != http.MethodHead {
		methodNotAllowed(w, "")
		return
	}
	a, ok := assets[r.URL.Path]
	if !ok {
		writeDetail(w, http.StatusNotFound, "Not Found")
		return
	}
	w.Header().Set("Content-Type", a.ctype)
	w.Header().Set("Etag", a.etag)
	http.ServeContent(w, r, a.file, a.modified, bytes.NewReader(mustStatic(a.file)))
}
